from docx import Document
from docx.shared import Inches, Pt

d=Document(); sec=d.sections[0]; sec.top_margin=sec.bottom_margin=Inches(.75)
style=d.styles['Normal']; style.font.name='Arial'; style.font.size=Pt(10)
def title(t): d.add_heading(t,1)
def para(t): d.add_paragraph(t)
def table(headers, rows):
 t=d.add_table(rows=1, cols=len(headers)); t.style='Table Grid'
 for c,v in zip(t.rows[0].cells,headers): c.text=v
 for row in rows:
  for c,v in zip(t.add_row().cells,row): c.text=v
def shot(t): para('[Screenshot placeholder: '+t+']')
d.add_heading('Spellstorm',0); para('A browser based vertical arcade survival game'); para('CC106 CLE Group Project Building Document')
para('Group members and proposed roles\nEufrey Magallanes - Lead Developer and Backend\nKarol Benedict Estrellas - Game Logic and Testing\nJohn Lloyd Escobar - UI UX and Documentation')
d.add_page_break(); title('I. SWOT Analysis of the Team and System')
for h,s in [('Strengths','Fast-paced dodge-and-fire gameplay, five Archon encounters, branching grimoire abilities and score progression create replay value. The project already includes account roles, a leaderboard, achievements, an admin area, parallax artwork, and responsive controls.'),('Weaknesses','The game is single-player and its extensive combat mechanics require careful balancing. Browser performance and touch controls need testing on different devices. PHP and database features require a configured server; online play and deployment have not yet been verified.'),('Opportunities','The leaderboard and achievements support friendly competition. Mobile controls can extend access to phones. Future cosmetics or additional content could improve replayability, subject to scope and testing.'),('Threats','Competition from established arcade games, player fatigue, performance drops during projectile-heavy encounters, hosting limits, and unstable connectivity may affect adoption and reliability.')]: d.add_heading(h,2); para(s)
para('Decisions: (1) Prioritize a playable, balanced campaign and verify each boss. (2) Assign backend, game testing, and interface responsibilities while reviewing work together. (3) Complete a working deployment and keep database backups and configuration separate from source code.')
title('II. Requirements and Scope'); para('Spellstorm is a single-player, browser-based vertical shooter. The player defends a spire through 50 circles, dodging enemies and selecting grimoire abilities and upgrades. Every tenth circle features an Archon. Surviving Circle 50 wins the run; losing all lives ends it. Players can restart, and signed-in players can save results and earn achievements.')
para('The project addresses the need for an accessible arcade game that runs in a browser and combines immediate gameplay with account-based progress. The scope includes guest play, registration and login, player profiles, scores, achievements, a guide, and an administrator control panel. Multiplayer, paid items, coin inventory and weapon attachments are not established features of the current implementation.')
table(['User','Access'],[['Guest','Play the game and view public game information; runs are not saved to an account.'],['Player','Sign in, play, save completed runs, view profile, achievements and leaderboard, and upload a profile image.'],['Administrator','Player access plus dashboard, player role management, guide and challenge management, and leaderboard moderation.']])
para('Technology: HTML, CSS, JavaScript, Bootstrap, PHP and PostgreSQL. The course guide names MySQL; instructor acceptance of PostgreSQL remains to be confirmed. Vercel is planned for deployment, not yet verified.')
title('III. System Design'); d.add_heading('ER Diagram',2)
para('users (1) to player_profiles (1); users (1) to game_runs (many); guide_categories (1) to guide_entries (many); users (1) to guide_entries (many, author); users and challenges have a many-to-many relationship through player_achievements, which can reference a game run.')
shot('Entity relationship diagram with primary and foreign keys')
d.add_heading('Role Access Matrix',2)
table(['Feature','Guest','Player','Admin'],[['Play game','Yes','Yes','Yes'],['Register or log in','Yes','Available','Available'],['Save runs and view profile','No','Own','Own'],['View leaderboard and achievements','Limited','Yes','Yes'],['Change own profile picture','No','Yes','Yes'],['Manage players, guide and challenges','No','No','Yes']])
d.add_heading('Folder Structure',2); para('index.html: game and landing page\nlogin.php, register.php, account.php: account pages\nadmin*.php: administration pages\nincludes/: sessions, database, account and shared layouts\njs/: game logic, rendering and controls\nassets/: styles, sprites and artwork\ndatabase/: PostgreSQL schema and supporting SQL\ntests/: automated checks\nconfig/: example and local database configuration')
d.add_heading('Page Flow',2); para('Home / Play → Register or Log in → Profile, Leaderboard or Achievements → Play → Results. Administrators can additionally enter the Control Panel to manage players and content.')
shot('Page flow or wireframe')
title('IV. Development Log'); para('The following is an implementation-stage summary. The group should add actual dates and confirm individual contributions before submission.')
table(['Stage','Work and evidence','Proposed responsibility'],[['Planning','Scope, SWOT, roles and database design','All members'],['Core game','Movement, combat, circles, bosses, progression: js/','Karol Benedict Estrellas'],['Application','Accounts, sessions, database and administration: includes/ and PHP pages','Eufrey Magallanes'],['Interface','Game artwork, layouts, navigation and Bootstrap: assets/styles/ and index.html','John Lloyd Escobar'],['Integration','Run saving, achievements, profile pictures and leaderboard','All members'],['Verification and deployment','Run tests, record results and prepare cloud deployment','All members']])
for s in ['SWOT analysis','Database tables','Registration and login','Game and boss encounter','Player profile and leaderboard','Administrator dashboard','Mobile view','Cloud deployment']: shot(s)
d.add_heading('Feature Code Excerpts',2); para('Login and password verification: includes/accounts.php uses password_verify. Session handling and role checks: includes/session.php. CRUD and prepared statements: includes/guide.php and admin-codex.php. Game flow and results: js/game-flow.js and js/run-sync.js. Profile picture validation: includes/avatar.php.')
title('V. Testing Record'); para('Automated checks previously run: 34 JavaScript tests and eight PHP test scripts passed. These do not replace the manual tests below. Record the actual result and date after each test.')
table(['ID','Feature and steps','Expected result','Actual / status'],[['T1','Log in with admin account','Admin dashboard opens','Not yet recorded'],['T2','Open admin URL as player','Access denied','Not yet recorded'],['T3','Register with valid and invalid inputs','Valid account created; invalid input rejected','Not yet recorded'],['T4','Create, edit and delete a guide entry','Changes persist with feedback','Not yet recorded'],['T5','Upload valid and invalid profile pictures','Valid image appears; invalid file rejected','Not yet recorded'],['T6','Play, lose, restart and win','Correct score and result appear','Not yet recorded'],['T7','Complete run while signed in','Run and achievements persist','Not yet recorded'],['T8','Test phone controls and navigation','Controls remain usable and readable','Not yet recorded'],['T9','Open public HTTPS URL and test accounts','Full application works remotely','Pending deployment']])
d.add_heading('Bugs Record',2); para('Boss difficulty: user feedback reports Circle 10 is easier than preceding circles. Rebalance and verify all boss encounters and phase health bars; fix status and tester results are not yet recorded.')
title('VI. Security and Scalability'); para('Passwords use password_hash and password_verify. Parameterized queries are used for submitted values. Output escaping, server-side validation, CSRF tokens, session ID regeneration, logout destruction and role checks are present in the PHP code. Profile uploads check image type, size and dimensions and store image data in the database; they do not use an uploaded filename. Credentials are separated into local configuration.')
para('Remaining work: verify every protected endpoint and form, test invalid uploads and direct URL access, confirm HTTPS after deployment, and document the MySQL decision. The browser submits game results, so a determined user can falsify scores. Add rate limits, stronger score verification, monitoring and backup procedures. For more users, consider a managed database, query indexes, caching, content delivery and load testing; ensure sessions work across the chosen hosting environment.')
title('VII. Cloud Deployment Record'); para('Planned platform: Vercel. Database: PostgreSQL connection configured for Supabase. Deployment has not been verified. Confirm a PHP runtime, session persistence, database access and HTTPS before release. Record the public URL, platform services, deployment steps, problems and fixes after deployment. Create dedicated admin and player accounts for grading.')
para('Public URL: Pending deployment\nDatabase deployment: Pending verification\nTest accounts: Pending creation\nDeployment issues and resolution: To be recorded')
title('VIII. Individual Reflections'); para('Each member must replace these prompts with their own first-person reflection. The course requires personal accounts; the group should not present assumed experiences as fact.')
for name,role in [('Eufrey Magallanes','backend, accounts and database'),('Karol Benedict Estrellas','game logic, balance and testing'),('John Lloyd Escobar','interface, accessibility and documentation')]:
 d.add_heading(name,2); para('Assigned focus: '+role+'. Describe your actual contribution and files, the hardest problem and how you addressed it, what you learned, how the SWOT compared with experience, and what you would improve next time.')
title('IX. Contribution Record and Meeting Notes'); table(['Member','Proposed focus','Evidence / actual contribution'],[['Eufrey Magallanes','Lead and backend','Confirm actual work and files'],['Karol Benedict Estrellas','Game logic and testing','Confirm actual work and files'],['John Lloyd Escobar','UI UX and documentation','Confirm actual work and files']]); para('Meeting dates, decisions, and contribution percentages: to be completed from the group’s records.')
title('X. README and Submission'); para('The project README explains controls and the source layout. Before submission, add complete setup instructions, platform and services, the live URL, group members, and dedicated test credentials. Submit runnable source, a matching SQL export with sample data, the building document, and a demonstration video. The video should cover both roles, CRUD, upload, security, database changes, deployment and gameplay; every member should speak or appear.')
para('Source link: To be supplied\nLive application: Pending deployment')
